  const publish = () => { if (!isAuthenticated) return startLogin(); if (!form.title.trim() || !form.locationName.trim() || !form.startsAt || form.description.trim().length < 20) return toast.error(t.required); if (form.levelAdmissionPolicy !== "declarative" && form.levelRequirementNote.trim().length < 10) return toast.error(locale === "fr" ? "Décrivez les prérequis de niveau pour cette sortie." : "Describe the level requirements for this outing."); createEvent.mutate({ title: form.title, description: form.description, locationName: form.locationName, startsAt: new Date(form.startsAt), latitude: form.latitude ? Number(form.latitude) : undefined, longitude: form.longitude ? Number(form.longitude) : undefined, distanceKm: Number(form.distanceKm), elevationGain: Number(form.elevationGain), durationMinutes: Number(form.durationMinutes), capacity: Number(form.capacity), difficulty: form.difficulty, difficultyOverrideReason: form.difficulty === recommendation.level ? undefined : form.difficultyOverrideReason.trim() || undefined, levelAdmissionPolicy: form.levelAdmissionPolicy, levelRequirementNote: form.levelAdmissionPolicy === "declarative" ? undefined : form.levelRequirementNote.trim(), terrainType: form.terrainType, technicality: form.technicality, exposureLevel: form.exposureLevel, navigationLevel: form.navigationLevel, routeCondition: form.routeCondition, visibility: form.visibility, requiresApproval: form.requiresApproval, carpoolEnabled: form.carpoolEnabled, outingType: form.outingType, bookingMode: form.bookingMode, priceCents: Math.round(Number(form.priceCents) * 100), gpxUrl: form.gpxUrl || undefined, manualRoutePoints: form.manualRoutePoints, manualRouteRoundTrip: form.manualRouteRoundTrip, initialTerrainLandmarks: form.initialTerrainLandmarks.map(landmark => ({ type: landmark.type, label: landmark.label, note: landmark.note || undefined, status: landmark.status, latitude: landmark.latitude ? Number(landmark.latitude) : undefined, longitude: landmark.longitude ? Number(landmark.longitude) : undefined, verifiedAt: landmark.verifiedAt ? new Date(`${landmark.verifiedAt}T12:00:00`) : undefined })), coverImageUrl: form.coverImageUrl || undefined, coverImageFocalX: form.coverImageFocalX ? Number(form.coverImageFocalX) : null, coverImageFocalY: form.coverImageFocalY ? Number(form.coverImageFocalY) : null, toiletsStatus: form.toiletsStatus, waterStatus: form.waterStatus, parkingStatus: form.parkingStatus, receptionStatus: form.receptionStatus, cellReceptionStatus: form.cellReceptionStatus, accessibilityNotes: form.accessibilityNotes || undefined, facilitiesNotes: form.facilitiesNotes || undefined, facilitiesVerifiedAt: form.facilitiesVerifiedAt ? new Date(form.facilitiesVerifiedAt) : undefined, participantGuidance: form.participantGuidance || undefined, cancellationPolicy: form.cancellationPolicy || undefined, initialLogistics: form.meetingPoint || form.meetingInstructions ? { meetingPoint: form.meetingPoint || undefined, meetingInstructions: form.meetingInstructions || undefined } : undefined, packingItems: form.packingItems }); };
