      <ManualRoutePlanner locale={locale} locationName={form.locationName} latitude={form.latitude ? Number(form.latitude) : undefined} longitude={form.longitude ? Number(form.longitude) : undefined} routePoints={form.manualRoutePoints} roundTrip={form.manualRouteRoundTrip} onRoundTripChange={manualRouteRoundTrip => setForm(current => ({ ...current, manualRouteRoundTrip }))} onRoutePointsChange={manualRoutePoints => setForm(current => ({ ...current, manualRoutePoints }))} landmarks={form.initialTerrainLandmarks} onLandmarksChange={initialTerrainLandmarks => setForm(current => ({ ...current, initialTerrainLandmarks }))} onMetrics={metrics => setForm(current => { const updated = { ...current, distanceKm: metrics.distanceKm !== undefined ? String(metrics.distanceKm) : current.distanceKm, durationMinutes: metrics.durationMinutes !== undefined ? String(metrics.durationMinutes) : current.durationMinutes, elevationGain: metrics.elevationGain !== undefined ? String(Math.round(metrics.elevationGain)) : current.elevationGain }; const selection = synchronizeDifficultySelection(difficultySelectionMode, updated.difficulty, recommendationFromForm(updated).level); return { ...updated, difficulty: selection.difficulty, difficultyOverrideReason: selection.shouldClearOverrideReason ? "" : updated.difficultyOverrideReason }; })} />
