    <Section title={t.marketplace}><div className="space-y-5"><ChoiceGrid label={t.type} value={form.outingType} onChange={value => set("outingType", value)} options={[{ value: "group_hike", label: t.group, hint: locale === "fr" ? "Sortie ouverte" : "Open outing" }, { value: "guided_hike", label: t.guided, hint: locale === "fr" ? "Encadrement annoncé" : "Guidance stated" }, { value: "training", label: t.training, hint: locale === "fr" ? "Objectif pratique" : "Practice goal" }, { value: "private_group", label: t.privateGroup, hint: locale === "fr" ? "Cercle restreint" : "Closed circle" }]} columns="grid-cols-2 sm:grid-cols-4" /><div className="grid gap-4 sm:grid-cols-[1fr_13rem]"><ChoiceGrid label={t.booking} value={form.bookingMode} onChange={value => set("bookingMode", value)} options={[{ value: "instant", label: t.instant, hint: locale === "fr" ? "Accès immédiat" : "Immediate access" }, { value: "request", label: t.request, hint: locale === "fr" ? "Validation avant accès" : "Review first" }]} /><Field label={t.price}><input inputMode="decimal" value={form.priceCents} onChange={event => set("priceCents", event.target.value)} placeholder="0" /></Field></div></div></Section>
