    const completed = step < activeStep;
    const tone = active ? "bg-[#1d493a] text-white shadow-sm" : completed ? "bg-[#eef6ea] text-[#3f7558]" : "text-[#99ad9f] hover:bg-[#f5f9f3] hover:text-[#527663]";
    return <button key={label} type="button" aria-current={active ? "step" : undefined} onClick={() => onSelect(step)} className={`min-h-12 min-w-0 rounded-xl px-1 py-2 text-center text-[10px] font-extrabold transition sm:text-xs ${tone}`}><span className={`mx-auto grid size-4 place-items-center rounded-full text-[9px] ${active ? "bg-white/20" : completed ? "bg-[#cfe7cc]" : "bg-[#edf2eb]"}`}>{completed ? <Check size={10} /> : step}</span><span className="mt-1 block whitespace-normal text-[9px] leading-none sm:text-xs">{label}</span></button>;
