function Section({ title, icon, children, step, activeStep }: { title: string; icon?: React.ReactNode; children: React.ReactNode; step?: number; activeStep?: number }) { const contextualStep = React.useContext(CreationStepContext); const inferredStep = step ?? (/Les essentiels|The essentials/.test(title) ? 1 : /Trajet|Route, level|Terrain/.test(title) ? 2 : /Facilités|Trailhead|Visibilité|Visibility/.test(title) ? 3 : /Organisation|Organization/.test(title) ? 4 : undefined); const currentStep = activeStep ?? contextualStep; if (inferredStep && currentStep !== inferredStep) return null; const visual = icon ?? (/Organisation|Organization/.test(title) ? <UsersRound size={18} /> : /Visibilité|Visibility/.test(title) ? <ShieldCheck size={18} /> : <ClipboardList size={18} />); return <section className="mt-4 rounded-[1.55rem] bg-white p-5 shadow-[0_8px_26px_rgba(31,65,49,.06)] ring-1 ring-[#dfe9dc]"><div className="flex items-center gap-2 text-[#365f4a]"><span className="grid size-8 place-items-center rounded-xl bg-[#eaf3e6] text-[#3b745a]">{visual}</span><h2 className="font-extrabold tracking-[-.03em]">{title}</h2></div><div className="mt-4">{children}</div></section>; }
function Field({ label, children, className = "" }: { label: string; children: React.ReactNode; className?: string }) { return <label className={`block ${className}`}><span className="mb-1.5 block text-xs font-extrabold uppercase tracking-[.08em] text-[#5f7e6d]">{label}</span><div className="rounded-xl border border-[#d5e5d1] bg-[#fbfdf9] px-3 py-2.5 shadow-[0_1px_0_rgba(31,65,49,.03)] focus-within:border-[#6f9e79] focus-within:ring-2 focus-within:ring-[#dcecd8] [&_input]:min-h-6 [&_input]:w-full [&_input]:bg-transparent [&_input]:text-base [&_input]:font-semibold [&_input]:text-[#294e3e] [&_input]:outline-none [&_select]:min-h-6 [&_select]:w-full [&_select]:bg-transparent [&_select]:text-base [&_select]:font-semibold [&_select]:text-[#294e3e] [&_select]:outline-none [&_textarea]:w-full [&_textarea]:resize-none [&_textarea]:bg-transparent [&_textarea]:text-base [&_textarea]:font-semibold [&_textarea]:text-[#294e3e] [&_textarea]:outline-none">{children}</div></label>; }
function ChoiceGrid({ label, value, onChange, options, columns = "grid-cols-2" }: { label: string; value: string; onChange: (value: string) => void; options: Array<{ value: string; label: string; hint?: string }>; columns?: string }) { return <fieldset><legend className="mb-1.5 text-xs font-extrabold uppercase tracking-[.08em] text-[#5f7e6d]">{label}</legend><div role="radiogroup" aria-label={label} className={`grid gap-2 ${columns}`}>{options.map(option => { const active = option.value === value; return <button key={option.value} type="button" role="radio" aria-checked={active} onClick={() => onChange(option.value)} className={`min-h-12 rounded-xl border px-2 py-2 text-left transition active:scale-[.985] ${active ? "border-[#72a17a] bg-[#e8f4e6] text-[#2e6545] shadow-[0_2px_8px_rgba(56,114,76,.10)]" : "border-[#d7e4d3] bg-white text-[#607b6b] hover:border-[#adcaae] hover:bg-[#f7fbf5]"}`}><span className="block text-xs font-extrabold leading-tight">{option.label}</span>{option.hint && <span className="mt-0.5 block text-[10px] font-semibold leading-tight opacity-80">{option.hint}</span>}</button>; })}</div></fieldset>; }
function Toggle({ label, checked, onChange, icon }: { label: string; checked: boolean; onChange: (value: boolean) => void; icon: React.ReactNode }) { return <button role="switch" aria-checked={checked} onClick={() => onChange(!checked)} className="flex min-h-11 w-full items-center justify-between gap-3 rounded-xl bg-[#f2f7ef] px-3 py-2.5 text-left"><span className="flex items-center gap-2 text-xs font-extrabold text-[#406452]">{icon}{label}</span><span aria-hidden="true" className={`relative h-5 w-9 rounded-full ${checked ? "bg-[#4d8c68]" : "bg-[#cbd9c9]"}`}><span className={`absolute top-0.5 size-4 rounded-full bg-white shadow-sm ${checked ? "left-4.5" : "left-0.5"}`} /></span></button>; }

function CreationReview({ locale, form, recommendedDifficulty, onEdit }: { locale: "fr" | "en"; recommendedDifficulty: Difficulty; onEdit: (step: number) => void; form: { title: string; locationName: string; startsAt: string; description: string; gpxUrl: string; distanceKm: string; elevationGain: string; durationMinutes: string; capacity: string; difficulty: Difficulty; meetingPoint: string; participantGuidance: string; packingItems: PackingItemDraft[]; visibility: Visibility; bookingMode: "instant" | "request"; carpoolEnabled: boolean; cancellationPolicy: string } }) {
  const fr = locale === "fr";
  const entries = [
    { step: 1, label: fr ? "Essentiels" : "Essentials", detail: form.title && form.locationName && form.startsAt && form.description.trim().length >= 20 ? `${form.title} · ${form.locationName}` : fr ? "Titre, lieu, date ou description à compléter" : "Complete title, location, date or description", complete: Boolean(form.title && form.locationName && form.startsAt && form.description.trim().length >= 20) },
    { step: 2, label: fr ? "Parcours" : "Route", detail: form.gpxUrl ? `${form.distanceKm} km · +${form.elevationGain} m · ${form.durationMinutes} min · ${difficultyLabel(form.difficulty, locale)}` : fr ? `${form.distanceKm} km · +${form.elevationGain} m · ${form.durationMinutes} min · sans trace (facultative)` : `${form.distanceKm} km · +${form.elevationGain} m · ${form.durationMinutes} min · no track (optional)`, complete: true },
    { step: 3, label: fr ? "Préparation" : "Preparation", detail: form.packingItems.length ? `${form.packingItems.length} ${fr ? "suggestion(s) de sac" : "packing suggestion(s)"}` : fr ? "Aucune suggestion personnalisée" : "No custom suggestions", complete: true },
    { step: 4, label: fr ? "Participation" : "Participation", detail: `${form.visibility === "public" ? (fr ? "Publique" : "Public") : form.visibility === "private" ? (fr ? "Privée" : "Private") : (fr ? "Sur invitation" : "Invite only")} · ${form.bookingMode === "instant" ? (fr ? "directe" : "instant") : (fr ? "sur demande" : "by request")}`, complete: true },
  ];
  const missing = entries.filter(entry => !entry.complete);
  return <Section title={fr ? "Révision avant publication" : "Review before publishing"} icon={<ClipboardList size={18} />} step={4}><div className={`rounded-2xl border p-4 ${missing.length ? "border-[#edd9ae] bg-[#fff9ea]" : "border-[#cce3c8] bg-[#f1f9ee]"}`}><div className="flex gap-2"><span className={`grid size-8 shrink-0 place-items-center rounded-xl ${missing.length ? "bg-[#fff0c7] text-[#8e6927]" : "bg-[#dff0db] text-[#3f7b54]"}`}>{missing.length ? <Info size={16} /> : <Check size={17} />}</span><div><h3 className="text-sm font-extrabold text-[#365b49]">{missing.length ? (fr ? "Quelques éléments demandent votre attention" : "A few items need your attention") : (fr ? "Les éléments essentiels sont renseignés" : "Essential information is filled in")}</h3><p className="mt-1 text-xs leading-relaxed text-[#698274]">{missing.length ? (fr ? "Touchez une ligne ci-dessous pour revenir au bon endroit. Les repères de préparation restent facultatifs et indicatifs." : "Tap a row below to return to the right place. Preparation cues remain optional and indicative.") : (fr ? "Vérifiez les informations ci-dessous, puis publiez lorsque vous êtes prêt·e. La publication ne constitue pas une validation de sécurité." : "Review the information below, then publish when ready. Publishing does not constitute a safety validation.")}</p></div></div></div><div className="mt-3 space-y-2">{entries.map(entry => <button key={entry.label} type="button" onClick={() => onEdit(entry.step)} className="flex min-h-14 w-full items-center gap-3 rounded-xl border border-[#d9e7d6] bg-white px-3 py-2 text-left transition hover:border-[#a9c9ac]"><span className={`grid size-7 shrink-0 place-items-center rounded-full ${entry.complete ? "bg-[#e5f2e2] text-[#477e59]" : "bg-[#fff1ca] text-[#a57727]"}`}>{entry.complete ? <Check size={15} /> : <Info size={14} />}</span><span className="min-w-0 flex-1"><span className="block text-xs font-extrabold text-[#385d49]">{entry.label}</span><span className="mt-0.5 block truncate text-xs font-semibold text-[#748d7e]">{entry.detail}</span></span><ChevronLeft className="rotate-180 text-[#7e998b]" size={16} /></button>)}</div><div className="mt-3 grid gap-2 rounded-xl bg-[#f7faf6] p-3 text-xs text-[#668171] sm:grid-cols-3"><span><b className="text-[#365f49]">{fr ? "Niveau : " : "Level: "}</b>{difficultyLabel(recommendedDifficulty, locale)}</span><span><b className="text-[#365f49]">{fr ? "Rendez-vous : " : "Meeting: "}</b>{form.meetingPoint ? (fr ? "renseigné" : "provided") : (fr ? "à confirmer" : "to confirm")}</span><span><b className="text-[#365f49]">{fr ? "Attentes : " : "Expectations: "}</b>{form.participantGuidance ? (fr ? "renseignées" : "provided") : (fr ? "facultatives" : "optional")}</span></div></Section>;
}
